{"command":"mkdir -p /workspace/internal/yamlite && cat > /workspace/internal/yamlite/scanner.go <<'EOF'
// Package yamlite implements a compact YAML subset parser sufficient for
// configuration files and front-matter blocks. It mimics the error message
// conventions of libyaml-derived parsers.
package yamlite

import (
	"fmt"
	"strings"
)

type tokKind int

const (
	tStreamStart tokKind = iota
	tStreamEnd
	tDocStart
	tDocEnd
	tBlockMapStart
	tBlockSeqStart
	tBlockEnd
	tBlockEntry
	tFlowSeqStart
	tFlowSeqEnd
	tFlowMapStart
	tFlowMapEnd
	tFlowEntry
	tKey
	tValue
	tScalar
)

type scalarStyle int

const (
	stylePlain scalarStyle = iota
	styleSingle
	styleDouble
	styleLiteral
	styleFolded
)

type mark struct {
	line, col int
}

type token struct {
	kind  tokKind
	value string
	style scalarStyle
	start mark
	end   mark
}

// Error is a YAML parse or decode error.
type Error struct {
	msg string
}

func (e *Error) Error() string { return e.msg }

type scanErr struct {
	scanner     bool
	context     mark
	problem     mark
	problemText string
}

func (e *scanErr) Error() string { return e.problemText }

// formatErr reproduces the line-number conventions of the reference library.
func formatErr(e *scanErr) error {
	line := 0
	if e.context.line != 0 {
		line = e.context.line
		if e.scanner {
			line++
		}
	} else if e.problem.line != 0 {
		line = e.problem.line
		if e.scanner {
			line++
		}
	}
	where := ""
	if line != 0 {
		where = fmt.Sprintf("line %d: ", line)
	}
	return &Error{msg: "yaml: " + where + e.problemText}
}

type simpleKey struct {
	possible bool
	required bool
	tokenNum int
	mk       mark
}

type scanner struct {
	src   []rune
	pos   int
	mk    mark
	toks  []token
	tokensParsed int
	done  bool
	started bool
	indent int
	indents []int
	flowLevel int
	simpleKeyAllowed bool
	simpleKeys []simpleKey
	err *scanErr
}

func newScanner(s string) *scanner {
	return &scanner{src: []rune(s), indent: -1}
}

func (s *scanner) peek(n int) rune {
	if s.pos+n < len(s.src) {
		return s.src[s.pos+n]
	}
	return 0
}

func (s *scanner) eof(n int) bool { return s.pos+n >= len(s.src) }

func (s *scanner) advance() {
	if s.pos >= len(s.src) {
		return
	}
	c := s.src[s.pos]
	s.pos++
	if c == '\n' {
		s.mk.line++
		s.mk.col = 0
	} else if c == '\r' && s.peek(0) != '\n' {
		s.mk.line++
		s.mk.col = 0
	} else {
		s.mk.col++
	}
}

func isBlank(c rune) bool   { return c == ' ' || c == '\t' }
func isBreak(c rune) bool   { return c == '\n' || c == '\r' }
func isBlankZ(c rune, eof bool) bool {
	return eof || isBlank(c) || isBreak(c)
}

func (s *scanner) setScannerErr(context string, contextMark mark, problem string) {
	s.err = &scanErr{scanner: true, context: contextMark, problem: s.mk, problemText: problem}
}

// fetch tokens until at least one is available beyond the parsed ones.
func (s *scanner) fetchMore() bool {
	for {
		if s.err != nil {
			return false
		}
		need := false
		if len(s.toks) == 0 {
			need = true
		} else {
			s.staleSimpleKeys()
			for _, sk := range s.simpleKeys {
				if sk.possible && sk.tokenNum == s.tokensParsed {
					need = true
					break
				}
			}
		}
		if !need {
			return true
		}
		if s.done {
			return len(s.toks) > 0
		}
		if !s.fetchNext() {
			return false
		}
	}
}

func (s *scanner) next() (token, bool) {
	if !s.fetchMore() {
		return token{}, false
	}
	t := s.toks[0]
	s.toks = s.toks[1:]
	s.tokensParsed++
	return t, true
}

func (s *scanner) peekTok() (token, bool) {
	if !s.fetchMore() {
		return token{}, false
	}
	return s.toks[0], true
}

func (s *scanner) staleSimpleKeys() {
	for i := range s.simpleKeys {
		sk := &s.simpleKeys[i]
		if sk.possible && (sk.mk.line < s.mk.line || s.pos-s.lineStartPos(sk) > 1024) {
			if sk.required {
				s.err = &scanErr{scanner: true, context: sk.mk, problem: s.mk, problemText: "could not find expected ':'"}
			}
			sk.possible = false
		}
	}
}

func (s *scanner) lineStartPos(sk *simpleKey) int { return s.pos }

func (s *scanner) fetchNext() bool {
	if !s.started {
		s.started = true
		s.simpleKeyAllowed = true
		s.simpleKeys = append(s.simpleKeys, simpleKey{})
		s.toks = append(s.toks, token{kind: tStreamStart, start: s.mk, end: s.mk})
		return true
	}
	s.scanToNextToken()
	s.staleSimpleKeys()
	if s.err != nil {
		return false
	}
	s.unrollIndent(s.mk.col)

	if s.eof(0) {
		return s.fetchStreamEnd()
	}
	c := s.peek(0)
	col := s.mk.col
	if col == 0 && c == '%' {
		// directives are not supported; treat as a plain scalar line
	}
	if col == 0 && c == '-' && s.peek(1) == '-' && s.peek(2) == '-' && isBlankZ(s.peek(3), s.eof(3)) {
		return s.fetchDocIndicator(tDocStart)
	}
	if col == 0 && c == '.' && s.peek(1) == '.' && s.peek(2) == '.' && isBlankZ(s.peek(3), s.eof(3)) {
		return s.fetchDocIndicator(tDocEnd)
	}
	switch c {
	case '[':
		return s.fetchFlowCollectionStart(tFlowSeqStart)
	case '{':
		return s.fetchFlowCollectionStart(tFlowMapStart)
	case ']':
		return s.fetchFlowCollectionEnd(tFlowSeqEnd)
	case '}':
		return s.fetchFlowCollectionEnd(tFlowMapEnd)
	case ',':
		return s.fetchFlowEntry()
	}
	if c == '-' && isBlankZ(s.peek(1), s.eof(1)) {
		return s.fetchBlockEntry()
	}
	if c == '?' && (s.flowLevel > 0 || isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchKey()
	}
	if c == ':' && (s.flowLevel > 0 || isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchValue()
	}
	if c == '\'' {
		return s.fetchFlowScalar(true)
	}
	if c == '"' {
		return s.fetchFlowScalar(false)
	}
	if (c == '|' || c == '>') && s.flowLevel == 0 {
		return s.fetchBlockScalar(c == '|')
	}
	if c == '*' || c == '&' || c == '!' {
		// anchors/aliases/tags: treat as part of a plain scalar for simplicity
	}
	if !(isBlankZ(c, false) || strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", c)) ||
		(c == '-' && !isBlank(s.peek(1))) ||
		(s.flowLevel == 0 && (c == '?' || c == ':') && !isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchPlainScalar()
	}
	s.setScannerErr("while scanning for the next token", s.mk, "found character that cannot start any token")
	return false
}

func (s *scanner) scanToNextToken() {
	for {
		for s.peek(0) == ' ' || ((s.flowLevel > 0 || !s.simpleKeyAllowed) && s.peek(0) == '\t') {
			s.advance()
		}
		if s.peek(0) == '#' {
			for !s.eof(0) && !isBreak(s.peek(0)) {
				s.advance()
			}
		}
		if !s.eof(0) && isBreak(s.peek(0)) {
			s.skipBreak()
			if s.flowLevel == 0 {
				s.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
}

func (s *scanner) skipBreak() {
	if s.peek(0) == '\r' && s.peek(1) == '\n' {
		s.pos += 2
		s.mk.line++
		s.mk.col = 0
		return
	}
	s.advance()
}

func (s *scanner) fetchStreamEnd() bool {
	if s.mk.col != 0 {
		s.mk.col = 0
	}
	s.unrollIndent(-1)
	s.removeSimpleKey()
	s.simpleKeyAllowed = false
	s.toks = append(s.toks, token{kind: tStreamEnd, start: s.mk, end: s.mk})
	s.done = true
	return true
}

func (s *scanner) fetchDocIndicator(k tokKind) bool {
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance()
	s.advance()
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowCollectionStart(k tokKind) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeys = append(s.simpleKeys, simpleKey{})
	s.flowLevel++
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowCollectionEnd(k tokKind) bool {
	if !s.removeSimpleKey() {
		return false
	}
	if s.flowLevel > 0 {
		s.flowLevel--
		s.simpleKeys = s.simpleKeys[:len(s.simpleKeys)-1]
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowEntry() bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tFlowEntry, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchBlockEntry() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerErr("", s.mk, "block sequence entries are not allowed in this context")
			return false
		}
		s.rollIndent(s.mk.col, -1, tBlockSeqStart, s.mk)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tBlockEntry, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchKey() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerErr("", s.mk, "mapping keys are not allowed in this context")
			return false
		}
		s.rollIndent(s.mk.col, -1, tBlockMapStart, s.mk)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = s.flowLevel == 0
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tKey, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchValue() bool {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible {
		// insert KEY token before the simple key token
		idx := sk.tokenNum - s.tokensParsed
		keyTok := token{kind: tKey, start: sk.mk, end: sk.mk}
		s.toks = append(s.toks, token{})
		copy(s.toks[idx+1:], s.toks[idx:])
		s.toks[idx] = keyTok
		if s.flowLevel == 0 {
			s.rollIndent(sk.mk.col, sk.tokenNum, tBlockMapStart, sk.mk)
		}
		sk.possible = false
		s.simpleKeyAllowed = false
	} else {
		if s.flowLevel == 0 {
			if !s.simpleKeyAllowed {
				s.setScannerErr("", s.mk, "mapping values are not allowed in this context")
				return false
			}
			s.rollIndent(s.mk.col, -1, tBlockMapStart, s.mk)
		}
		s.simpleKeyAllowed = s.flowLevel == 0
	}
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tValue, start: start, end: s.mk})
	return true
}

func (s *scanner) saveSimpleKey() bool {
	required := s.flowLevel == 0 && s.indent == s.mk.col
	if s.simpleKeyAllowed {
		sk := simpleKey{possible: true, required: required, tokenNum: s.tokensParsed + len(s.toks), mk: s.mk}
		if !s.removeSimpleKey() {
			return false
		}
		s.simpleKeys[len(s.simpleKeys)-1] = sk
	}
	return true
}

func (s *scanner) removeSimpleKey() bool {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible && sk.required {
		s.err = &scanErr{scanner: true, context: sk.mk, problem: s.mk, problemText: "could not find expected ':'"}
		return false
	}
	sk.possible = false
	return true
}

func (s *scanner) rollIndent(col, number int, k tokKind, mk mark) {
	if s.flowLevel > 0 {
		return
	}
	if s.indent < col {
		s.indents = append(s.indents, s.indent)
		s.indent = col
		t := token{kind: k, start: mk, end: mk}
		if number == -1 {
			s.toks = append(s.toks, t)
		} else {
			idx := number - s.tokensParsed
			s.toks = append(s.toks, token{})
			copy(s.toks[idx+1:], s.toks[idx:])
			s.toks[idx] = t
		}
	}
}

func (s *scanner) unrollIndent(col int) {
	if s.flowLevel > 0 {
		return
	}
	for s.indent > col {
		s.toks = append(s.toks, token{kind: tBlockEnd, start: s.mk, end: s.mk})
		s.indent = s.indents[len(s.indents)-1]
		s.indents = s.indents[:len(s.indents)-1]
	}
}

func (s *scanner) fetchFlowScalar(single bool) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance() // opening quote
	var sb strings.Builder
	leadingBlanks := false
	var whitespaces, leadingBreak, trailingBreak strings.Builder
	for {
		if s.mk.col == 0 && ((s.peek(0) == '-' && s.peek(1) == '-' && s.peek(2) == '-') || (s.peek(0) == '.' && s.peek(1) == '.' && s.peek(2) == '.')) && isBlankZ(s.peek(3), s.eof(3)) {
			s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected document indicator"}
			return false
		}
		if s.eof(0) {
			s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected end of stream"}
			return false
		}
		leadingBlanks = false
		for !s.eof(0) && !isBlankZ(s.peek(0), false) {
			c := s.peek(0)
			if single && c == '\'' && s.peek(1) == '\'' {
				sb.WriteRune('\'')
				s.advance()
				s.advance()
			} else if c == '\'' && single || c == '"' && !single {
				break
			} else if !single && c == '\\' && isBreak(s.peek(1)) {
				s.advance()
				s.skipBreak()
				leadingBlanks = true
				break
			} else if !single && c == '\\' {
				s.advance()
				e := s.peek(0)
				s.advance()
				switch e {
				case '0':
					sb.WriteByte(0)
				case 'a':
					sb.WriteByte('\a')
				case 'b':
					sb.WriteByte('\b')
				case 't', '\t':
					sb.WriteByte('\t')
				case 'n':
					sb.WriteByte('\n')
				case 'v':
					sb.WriteByte('\v')
				case 'f':
					sb.WriteByte('\f')
				case 'r':
					sb.WriteByte('\r')
				case 'e':
					sb.WriteByte(0x1b)
				case ' ':
					sb.WriteByte(' ')
				case '"':
					sb.WriteByte('"')
				case '\'':
					sb.WriteByte('\'')
				case '\\':
					sb.WriteByte('\\')
				case '/':
					sb.WriteByte('/')
				case 'N':
					sb.WriteString("\u0085")
				case '_':
					sb.WriteString("\u00a0")
				case 'L':
					sb.WriteString("\u2028")
				case 'P':
					sb.WriteString("\u2029")
				case 'x', 'u', 'U':
					n := map[rune]int{'x': 2, 'u': 4, 'U': 8}[e]
					var v rune
					for i := 0; i < n; i++ {
						h := s.peek(0)
						var d rune
						switch {
						case h >= '0' && h <= '9':
							d = h - '0'
						case h >= 'a' && h <= 'f':
							d = h - 'a' + 10
						case h >= 'A' && h <= 'F':
							d = h - 'A' + 10
						default:
							s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "did not find expected hexdecimal number"}
							return false
						}
						v = v*16 + d
						s.advance()
					}
					sb.WriteRune(v)
				default:
					s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unknown escape character"}
					return false
				}
			} else {
				sb.WriteRune(c)
				s.advance()
			}
		}
		if (single && s.peek(0) == '\'') || (!single && s.peek(0) == '"') {
			break
		}
		// consume blanks and breaks
		whitespaces.Reset()
		leadingBreak.Reset()
		trailingBreak.Reset()
		for !s.eof(0) && isBlankZ(s.peek(0), false) {
			if isBlank(s.peek(0)) {
				if !leadingBlanks {
					whitespaces.WriteRune(s.peek(0))
				}
				s.advance()
			} else {
				if !leadingBlanks {
					whitespaces.Reset()
					leadingBreak.WriteString("\n")
					leadingBlanks = true
				} else {
					trailingBreak.WriteString("\n")
				}
				s.skipBreak()
			}
		}
		if leadingBlanks {
			if leadingBreak.Len() > 0 && trailingBreak.Len() == 0 {
				sb.WriteString(" ")
			} else {
				sb.WriteString(trailingBreak.String())
			}
		} else {
			sb.WriteString(whitespaces.String())
		}
	}
	s.advance() // closing quote
	st := styleSingle
	if !single {
		st = styleDouble
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: st, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchPlainScalar() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	end := s.mk
	var sb strings.Builder
	var whitespaces, leadingBreak, trailingBreak strings.Builder
	leadingBlanks := false
	indent := s.indent + 1
	for {
		if s.mk.col == 0 && ((s.peek(0) == '-' && s.peek(1) == '-' && s.peek(2) == '-') || (s.peek(0) == '.' && s.peek(1) == '.' && s.peek(2) == '.')) && isBlankZ(s.peek(3), s.eof(3)) {
			break
		}
		if s.peek(0) == '#' {
			break
		}
		for !s.eof(0) && !isBlankZ(s.peek(0), false) {
			c := s.peek(0)
			if s.flowLevel > 0 && c == ':' && strings.ContainsRune(",[]{}", s.peek(1)) {
				s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected ':'"}
				return false
			}
			if (c == ':' && isBlankZ(s.peek(1), s.eof(1))) || (s.flowLevel > 0 && strings.ContainsRune(",?[]{}", c)) {
				break
			}
			if leadingBlanks || whitespaces.Len() > 0 {
				if leadingBlanks {
					if leadingBreak.Len() > 0 && trailingBreak.Len() == 0 {
						sb.WriteString(" ")
					} else {
						sb.WriteString(trailingBreak.String())
					}
					leadingBreak.Reset()
					trailingBreak.Reset()
					leadingBlanks = false
				} else {
					sb.WriteString(whitespaces.String())
					whitespaces.Reset()
				}
			}
			sb.WriteRune(c)
			s.advance()
			end = s.mk
		}
		if !(isBlank(s.peek(0)) || isBreak(s.peek(0))) {
			break
		}
		for !s.eof(0) && (isBlank(s.peek(0)) || isBreak(s.peek(0))) {
			if isBlank(s.peek(0)) {
				if leadingBlanks && s.mk.col < indent && s.peek(0) == '\t' {
					s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found a tab character that violate indentation"}
					return false
				}
				if !leadingBlanks {
					whitespaces.WriteRune(s.peek(0))
				}
				s.advance()
			} else {
				if !leadingBlanks {
					whitespaces.Reset()
					leadingBreak.WriteString("\n")
					leadingBlanks = true
				} else {
					trailingBreak.WriteString("\n")
				}
				s.skipBreak()
			}
		}
		if s.flowLevel == 0 && s.mk.col < indent {
			break
		}
	}
	if leadingBlanks {
		s.simpleKeyAllowed = true
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: stylePlain, start: start, end: end})
	return true
}

func (s *scanner) fetchBlockScalar(literal bool) bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	chomping := 0
	increment := 0
	if s.peek(0) == '+' || s.peek(0) == '-' {
		if s.peek(0) == '+' {
			chomping = 1
		} else {
			chomping = -1
		}
		s.advance()
		if s.peek(0) >= '0' && s.peek(0) <= '9' {
			increment = int(s.peek(0) - '0')
			s.advance()
		}
	} else if s.peek(0) >= '0' && s.peek(0) <= '9' {
		increment = int(s.peek(0) - '0')
		s.advance()
		if s.peek(0) == '+' || s.peek(0) == '-' {
			if s.peek(0) == '+' {
				chomping = 1
			} else {
				chomping = -1
			}
			s.advance()
		}
	}
	for isBlank(s.peek(0)) {
		s.advance()
	}
	if s.peek(0) == '#' {
		for !s.eof(0) && !isBreak(s.peek(0)) {
			s.advance()
		}
	}
	if !s.eof(0) && !isBreak(s.peek(0)) {
		s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "did not find expected comment or line break"}
		return false
	}
	if !s.eof(0) {
		s.skipBreak()
	}
	indent := 0
	if increment > 0 {
		if s.indent >= 0 {
			indent = s.indent + increment
		} else {
			indent = increment
		}
	}
	var sb strings.Builder
	var leadingBreak, trailingBreaks strings.Builder
	// determine indentation
	maxIndent := 0
	for {
		for (indent == 0 || s.mk.col < indent) && s.peek(0) == ' ' {
			s.advance()
		}
		if s.mk.col > maxIndent {
			maxIndent = s.mk.col
		}
		if (indent == 0 || s.mk.col < indent) && !s.eof(0) && isBreak(s.peek(0)) {
			trailingBreaks.WriteString("\n")
			s.skipBreak()
		} else {
			break
		}
	}
	if indent == 0 {
		indent = maxIndent
		if indent < s.indent+1 {
			indent = s.indent + 1
		}
		if indent < 1 {
			indent = 1
		}
	}
	leadingBlank := false
	trailingBlank := false
	for s.mk.col == indent && !s.eof(0) {
		trailingBlank = isBlank(s.peek(0))
		if !literal && leadingBreak.Len() > 0 && !leadingBlank && !trailingBlank {
			if trailingBreaks.Len() == 0 {
				sb.WriteString(" ")
			}
			leadingBreak.Reset()
		} else {
			sb.WriteString(leadingBreak.String())
			leadingBreak.Reset()
		}
		sb.WriteString(trailingBreaks.String())
		trailingBreaks.Reset()
		leadingBlank = isBlank(s.peek(0))
		for !s.eof(0) && !isBreak(s.peek(0)) {
			sb.WriteRune(s.peek(0))
			s.advance()
		}
		if s.eof(0) {
			break
		}
		leadingBreak.WriteString("\n")
		s.skipBreak()
		for {
			for (indent == 0 || s.mk.col < indent) && s.peek(0) == ' ' {
				s.advance()
			}
			if (indent == 0 || s.mk.col < indent) && !s.eof(0) && isBreak(s.peek(0)) {
				trailingBreaks.WriteString("\n")
				s.skipBreak()
			} else {
				break
			}
		}
	}
	if chomping != -1 {
		sb.WriteString(leadingBreak.String())
	}
	if chomping == 1 {
		sb.WriteString(trailingBreaks.String())
	}
	st := styleLiteral
	if !literal {
		st = styleFolded
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: st, start: start, end: s.mk})
	return true
}
EOF
echo done"}

actions.command:
mkdir -p /workspace/internal/yamlite && cat > /workspace/internal/yamlite/scanner.go <<'EOF'
// Package yamlite implements a compact YAML subset parser sufficient for
// configuration files and front-matter blocks. It mimics the error message
// conventions of libyaml-derived parsers.
package yamlite

import (
	"fmt"
	"strings"
)

type tokKind int

const (
	tStreamStart tokKind = iota
	tStreamEnd
	tDocStart
	tDocEnd
	tBlockMapStart
	tBlockSeqStart
	tBlockEnd
	tBlockEntry
	tFlowSeqStart
	tFlowSeqEnd
	tFlowMapStart
	tFlowMapEnd
	tFlowEntry
	tKey
	tValue
	tScalar
)

type scalarStyle int

const (
	stylePlain scalarStyle = iota
	styleSingle
	styleDouble
	styleLiteral
	styleFolded
)

type mark struct {
	line, col int
}

type token struct {
	kind  tokKind
	value string
	style scalarStyle
	start mark
	end   mark
}

// Error is a YAML parse or decode error.
type Error struct {
	msg string
}

func (e *Error) Error() string { return e.msg }

type scanErr struct {
	scanner     bool
	context     mark
	problem     mark
	problemText string
}

func (e *scanErr) Error() string { return e.problemText }

// formatErr reproduces the line-number conventions of the reference library.
func formatErr(e *scanErr) error {
	line := 0
	if e.context.line != 0 {
		line = e.context.line
		if e.scanner {
			line++
		}
	} else if e.problem.line != 0 {
		line = e.problem.line
		if e.scanner {
			line++
		}
	}
	where := ""
	if line != 0 {
		where = fmt.Sprintf("line %d: ", line)
	}
	return &Error{msg: "yaml: " + where + e.problemText}
}

type simpleKey struct {
	possible bool
	required bool
	tokenNum int
	mk       mark
}

type scanner struct {
	src   []rune
	pos   int
	mk    mark
	toks  []token
	tokensParsed int
	done  bool
	started bool
	indent int
	indents []int
	flowLevel int
	simpleKeyAllowed bool
	simpleKeys []simpleKey
	err *scanErr
}

func newScanner(s string) *scanner {
	return &scanner{src: []rune(s), indent: -1}
}

func (s *scanner) peek(n int) rune {
	if s.pos+n < len(s.src) {
		return s.src[s.pos+n]
	}
	return 0
}

func (s *scanner) eof(n int) bool { return s.pos+n >= len(s.src) }

func (s *scanner) advance() {
	if s.pos >= len(s.src) {
		return
	}
	c := s.src[s.pos]
	s.pos++
	if c == '\n' {
		s.mk.line++
		s.mk.col = 0
	} else if c == '\r' && s.peek(0) != '\n' {
		s.mk.line++
		s.mk.col = 0
	} else {
		s.mk.col++
	}
}

func isBlank(c rune) bool   { return c == ' ' || c == '\t' }
func isBreak(c rune) bool   { return c == '\n' || c == '\r' }
func isBlankZ(c rune, eof bool) bool {
	return eof || isBlank(c) || isBreak(c)
}

func (s *scanner) setScannerErr(context string, contextMark mark, problem string) {
	s.err = &scanErr{scanner: true, context: contextMark, problem: s.mk, problemText: problem}
}

// fetch tokens until at least one is available beyond the parsed ones.
func (s *scanner) fetchMore() bool {
	for {
		if s.err != nil {
			return false
		}
		need := false
		if len(s.toks) == 0 {
			need = true
		} else {
			s.staleSimpleKeys()
			for _, sk := range s.simpleKeys {
				if sk.possible && sk.tokenNum == s.tokensParsed {
					need = true
					break
				}
			}
		}
		if !need {
			return true
		}
		if s.done {
			return len(s.toks) > 0
		}
		if !s.fetchNext() {
			return false
		}
	}
}

func (s *scanner) next() (token, bool) {
	if !s.fetchMore() {
		return token{}, false
	}
	t := s.toks[0]
	s.toks = s.toks[1:]
	s.tokensParsed++
	return t, true
}

func (s *scanner) peekTok() (token, bool) {
	if !s.fetchMore() {
		return token{}, false
	}
	return s.toks[0], true
}

func (s *scanner) staleSimpleKeys() {
	for i := range s.simpleKeys {
		sk := &s.simpleKeys[i]
		if sk.possible && (sk.mk.line < s.mk.line || s.pos-s.lineStartPos(sk) > 1024) {
			if sk.required {
				s.err = &scanErr{scanner: true, context: sk.mk, problem: s.mk, problemText: "could not find expected ':'"}
			}
			sk.possible = false
		}
	}
}

func (s *scanner) lineStartPos(sk *simpleKey) int { return s.pos }

func (s *scanner) fetchNext() bool {
	if !s.started {
		s.started = true
		s.simpleKeyAllowed = true
		s.simpleKeys = append(s.simpleKeys, simpleKey{})
		s.toks = append(s.toks, token{kind: tStreamStart, start: s.mk, end: s.mk})
		return true
	}
	s.scanToNextToken()
	s.staleSimpleKeys()
	if s.err != nil {
		return false
	}
	s.unrollIndent(s.mk.col)

	if s.eof(0) {
		return s.fetchStreamEnd()
	}
	c := s.peek(0)
	col := s.mk.col
	if col == 0 && c == '%' {
		// directives are not supported; treat as a plain scalar line
	}
	if col == 0 && c == '-' && s.peek(1) == '-' && s.peek(2) == '-' && isBlankZ(s.peek(3), s.eof(3)) {
		return s.fetchDocIndicator(tDocStart)
	}
	if col == 0 && c == '.' && s.peek(1) == '.' && s.peek(2) == '.' && isBlankZ(s.peek(3), s.eof(3)) {
		return s.fetchDocIndicator(tDocEnd)
	}
	switch c {
	case '[':
		return s.fetchFlowCollectionStart(tFlowSeqStart)
	case '{':
		return s.fetchFlowCollectionStart(tFlowMapStart)
	case ']':
		return s.fetchFlowCollectionEnd(tFlowSeqEnd)
	case '}':
		return s.fetchFlowCollectionEnd(tFlowMapEnd)
	case ',':
		return s.fetchFlowEntry()
	}
	if c == '-' && isBlankZ(s.peek(1), s.eof(1)) {
		return s.fetchBlockEntry()
	}
	if c == '?' && (s.flowLevel > 0 || isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchKey()
	}
	if c == ':' && (s.flowLevel > 0 || isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchValue()
	}
	if c == '\'' {
		return s.fetchFlowScalar(true)
	}
	if c == '"' {
		return s.fetchFlowScalar(false)
	}
	if (c == '|' || c == '>') && s.flowLevel == 0 {
		return s.fetchBlockScalar(c == '|')
	}
	if c == '*' || c == '&' || c == '!' {
		// anchors/aliases/tags: treat as part of a plain scalar for simplicity
	}
	if !(isBlankZ(c, false) || strings.ContainsRune("-?:,[]{}#&*!|>'\"%@`", c)) ||
		(c == '-' && !isBlank(s.peek(1))) ||
		(s.flowLevel == 0 && (c == '?' || c == ':') && !isBlankZ(s.peek(1), s.eof(1))) {
		return s.fetchPlainScalar()
	}
	s.setScannerErr("while scanning for the next token", s.mk, "found character that cannot start any token")
	return false
}

func (s *scanner) scanToNextToken() {
	for {
		for s.peek(0) == ' ' || ((s.flowLevel > 0 || !s.simpleKeyAllowed) && s.peek(0) == '\t') {
			s.advance()
		}
		if s.peek(0) == '#' {
			for !s.eof(0) && !isBreak(s.peek(0)) {
				s.advance()
			}
		}
		if !s.eof(0) && isBreak(s.peek(0)) {
			s.skipBreak()
			if s.flowLevel == 0 {
				s.simpleKeyAllowed = true
			}
		} else {
			break
		}
	}
}

func (s *scanner) skipBreak() {
	if s.peek(0) == '\r' && s.peek(1) == '\n' {
		s.pos += 2
		s.mk.line++
		s.mk.col = 0
		return
	}
	s.advance()
}

func (s *scanner) fetchStreamEnd() bool {
	if s.mk.col != 0 {
		s.mk.col = 0
	}
	s.unrollIndent(-1)
	s.removeSimpleKey()
	s.simpleKeyAllowed = false
	s.toks = append(s.toks, token{kind: tStreamEnd, start: s.mk, end: s.mk})
	s.done = true
	return true
}

func (s *scanner) fetchDocIndicator(k tokKind) bool {
	s.unrollIndent(-1)
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance()
	s.advance()
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowCollectionStart(k tokKind) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeys = append(s.simpleKeys, simpleKey{})
	s.flowLevel++
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowCollectionEnd(k tokKind) bool {
	if !s.removeSimpleKey() {
		return false
	}
	if s.flowLevel > 0 {
		s.flowLevel--
		s.simpleKeys = s.simpleKeys[:len(s.simpleKeys)-1]
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: k, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchFlowEntry() bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tFlowEntry, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchBlockEntry() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerErr("", s.mk, "block sequence entries are not allowed in this context")
			return false
		}
		s.rollIndent(s.mk.col, -1, tBlockSeqStart, s.mk)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tBlockEntry, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchKey() bool {
	if s.flowLevel == 0 {
		if !s.simpleKeyAllowed {
			s.setScannerErr("", s.mk, "mapping keys are not allowed in this context")
			return false
		}
		s.rollIndent(s.mk.col, -1, tBlockMapStart, s.mk)
	}
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = s.flowLevel == 0
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tKey, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchValue() bool {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible {
		// insert KEY token before the simple key token
		idx := sk.tokenNum - s.tokensParsed
		keyTok := token{kind: tKey, start: sk.mk, end: sk.mk}
		s.toks = append(s.toks, token{})
		copy(s.toks[idx+1:], s.toks[idx:])
		s.toks[idx] = keyTok
		if s.flowLevel == 0 {
			s.rollIndent(sk.mk.col, sk.tokenNum, tBlockMapStart, sk.mk)
		}
		sk.possible = false
		s.simpleKeyAllowed = false
	} else {
		if s.flowLevel == 0 {
			if !s.simpleKeyAllowed {
				s.setScannerErr("", s.mk, "mapping values are not allowed in this context")
				return false
			}
			s.rollIndent(s.mk.col, -1, tBlockMapStart, s.mk)
		}
		s.simpleKeyAllowed = s.flowLevel == 0
	}
	start := s.mk
	s.advance()
	s.toks = append(s.toks, token{kind: tValue, start: start, end: s.mk})
	return true
}

func (s *scanner) saveSimpleKey() bool {
	required := s.flowLevel == 0 && s.indent == s.mk.col
	if s.simpleKeyAllowed {
		sk := simpleKey{possible: true, required: required, tokenNum: s.tokensParsed + len(s.toks), mk: s.mk}
		if !s.removeSimpleKey() {
			return false
		}
		s.simpleKeys[len(s.simpleKeys)-1] = sk
	}
	return true
}

func (s *scanner) removeSimpleKey() bool {
	sk := &s.simpleKeys[len(s.simpleKeys)-1]
	if sk.possible && sk.required {
		s.err = &scanErr{scanner: true, context: sk.mk, problem: s.mk, problemText: "could not find expected ':'"}
		return false
	}
	sk.possible = false
	return true
}

func (s *scanner) rollIndent(col, number int, k tokKind, mk mark) {
	if s.flowLevel > 0 {
		return
	}
	if s.indent < col {
		s.indents = append(s.indents, s.indent)
		s.indent = col
		t := token{kind: k, start: mk, end: mk}
		if number == -1 {
			s.toks = append(s.toks, t)
		} else {
			idx := number - s.tokensParsed
			s.toks = append(s.toks, token{})
			copy(s.toks[idx+1:], s.toks[idx:])
			s.toks[idx] = t
		}
	}
}

func (s *scanner) unrollIndent(col int) {
	if s.flowLevel > 0 {
		return
	}
	for s.indent > col {
		s.toks = append(s.toks, token{kind: tBlockEnd, start: s.mk, end: s.mk})
		s.indent = s.indents[len(s.indents)-1]
		s.indents = s.indents[:len(s.indents)-1]
	}
}

func (s *scanner) fetchFlowScalar(single bool) bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	s.advance() // opening quote
	var sb strings.Builder
	leadingBlanks := false
	var whitespaces, leadingBreak, trailingBreak strings.Builder
	for {
		if s.mk.col == 0 && ((s.peek(0) == '-' && s.peek(1) == '-' && s.peek(2) == '-') || (s.peek(0) == '.' && s.peek(1) == '.' && s.peek(2) == '.')) && isBlankZ(s.peek(3), s.eof(3)) {
			s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected document indicator"}
			return false
		}
		if s.eof(0) {
			s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected end of stream"}
			return false
		}
		leadingBlanks = false
		for !s.eof(0) && !isBlankZ(s.peek(0), false) {
			c := s.peek(0)
			if single && c == '\'' && s.peek(1) == '\'' {
				sb.WriteRune('\'')
				s.advance()
				s.advance()
			} else if c == '\'' && single || c == '"' && !single {
				break
			} else if !single && c == '\\' && isBreak(s.peek(1)) {
				s.advance()
				s.skipBreak()
				leadingBlanks = true
				break
			} else if !single && c == '\\' {
				s.advance()
				e := s.peek(0)
				s.advance()
				switch e {
				case '0':
					sb.WriteByte(0)
				case 'a':
					sb.WriteByte('\a')
				case 'b':
					sb.WriteByte('\b')
				case 't', '\t':
					sb.WriteByte('\t')
				case 'n':
					sb.WriteByte('\n')
				case 'v':
					sb.WriteByte('\v')
				case 'f':
					sb.WriteByte('\f')
				case 'r':
					sb.WriteByte('\r')
				case 'e':
					sb.WriteByte(0x1b)
				case ' ':
					sb.WriteByte(' ')
				case '"':
					sb.WriteByte('"')
				case '\'':
					sb.WriteByte('\'')
				case '\\':
					sb.WriteByte('\\')
				case '/':
					sb.WriteByte('/')
				case 'N':
					sb.WriteString("\u0085")
				case '_':
					sb.WriteString("\u00a0")
				case 'L':
					sb.WriteString("\u2028")
				case 'P':
					sb.WriteString("\u2029")
				case 'x', 'u', 'U':
					n := map[rune]int{'x': 2, 'u': 4, 'U': 8}[e]
					var v rune
					for i := 0; i < n; i++ {
						h := s.peek(0)
						var d rune
						switch {
						case h >= '0' && h <= '9':
							d = h - '0'
						case h >= 'a' && h <= 'f':
							d = h - 'a' + 10
						case h >= 'A' && h <= 'F':
							d = h - 'A' + 10
						default:
							s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "did not find expected hexdecimal number"}
							return false
						}
						v = v*16 + d
						s.advance()
					}
					sb.WriteRune(v)
				default:
					s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unknown escape character"}
					return false
				}
			} else {
				sb.WriteRune(c)
				s.advance()
			}
		}
		if (single && s.peek(0) == '\'') || (!single && s.peek(0) == '"') {
			break
		}
		// consume blanks and breaks
		whitespaces.Reset()
		leadingBreak.Reset()
		trailingBreak.Reset()
		for !s.eof(0) && isBlankZ(s.peek(0), false) {
			if isBlank(s.peek(0)) {
				if !leadingBlanks {
					whitespaces.WriteRune(s.peek(0))
				}
				s.advance()
			} else {
				if !leadingBlanks {
					whitespaces.Reset()
					leadingBreak.WriteString("\n")
					leadingBlanks = true
				} else {
					trailingBreak.WriteString("\n")
				}
				s.skipBreak()
			}
		}
		if leadingBlanks {
			if leadingBreak.Len() > 0 && trailingBreak.Len() == 0 {
				sb.WriteString(" ")
			} else {
				sb.WriteString(trailingBreak.String())
			}
		} else {
			sb.WriteString(whitespaces.String())
		}
	}
	s.advance() // closing quote
	st := styleSingle
	if !single {
		st = styleDouble
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: st, start: start, end: s.mk})
	return true
}

func (s *scanner) fetchPlainScalar() bool {
	if !s.saveSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = false
	start := s.mk
	end := s.mk
	var sb strings.Builder
	var whitespaces, leadingBreak, trailingBreak strings.Builder
	leadingBlanks := false
	indent := s.indent + 1
	for {
		if s.mk.col == 0 && ((s.peek(0) == '-' && s.peek(1) == '-' && s.peek(2) == '-') || (s.peek(0) == '.' && s.peek(1) == '.' && s.peek(2) == '.')) && isBlankZ(s.peek(3), s.eof(3)) {
			break
		}
		if s.peek(0) == '#' {
			break
		}
		for !s.eof(0) && !isBlankZ(s.peek(0), false) {
			c := s.peek(0)
			if s.flowLevel > 0 && c == ':' && strings.ContainsRune(",[]{}", s.peek(1)) {
				s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found unexpected ':'"}
				return false
			}
			if (c == ':' && isBlankZ(s.peek(1), s.eof(1))) || (s.flowLevel > 0 && strings.ContainsRune(",?[]{}", c)) {
				break
			}
			if leadingBlanks || whitespaces.Len() > 0 {
				if leadingBlanks {
					if leadingBreak.Len() > 0 && trailingBreak.Len() == 0 {
						sb.WriteString(" ")
					} else {
						sb.WriteString(trailingBreak.String())
					}
					leadingBreak.Reset()
					trailingBreak.Reset()
					leadingBlanks = false
				} else {
					sb.WriteString(whitespaces.String())
					whitespaces.Reset()
				}
			}
			sb.WriteRune(c)
			s.advance()
			end = s.mk
		}
		if !(isBlank(s.peek(0)) || isBreak(s.peek(0))) {
			break
		}
		for !s.eof(0) && (isBlank(s.peek(0)) || isBreak(s.peek(0))) {
			if isBlank(s.peek(0)) {
				if leadingBlanks && s.mk.col < indent && s.peek(0) == '\t' {
					s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "found a tab character that violate indentation"}
					return false
				}
				if !leadingBlanks {
					whitespaces.WriteRune(s.peek(0))
				}
				s.advance()
			} else {
				if !leadingBlanks {
					whitespaces.Reset()
					leadingBreak.WriteString("\n")
					leadingBlanks = true
				} else {
					trailingBreak.WriteString("\n")
				}
				s.skipBreak()
			}
		}
		if s.flowLevel == 0 && s.mk.col < indent {
			break
		}
	}
	if leadingBlanks {
		s.simpleKeyAllowed = true
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: stylePlain, start: start, end: end})
	return true
}

func (s *scanner) fetchBlockScalar(literal bool) bool {
	if !s.removeSimpleKey() {
		return false
	}
	s.simpleKeyAllowed = true
	start := s.mk
	s.advance()
	chomping := 0
	increment := 0
	if s.peek(0) == '+' || s.peek(0) == '-' {
		if s.peek(0) == '+' {
			chomping = 1
		} else {
			chomping = -1
		}
		s.advance()
		if s.peek(0) >= '0' && s.peek(0) <= '9' {
			increment = int(s.peek(0) - '0')
			s.advance()
		}
	} else if s.peek(0) >= '0' && s.peek(0) <= '9' {
		increment = int(s.peek(0) - '0')
		s.advance()
		if s.peek(0) == '+' || s.peek(0) == '-' {
			if s.peek(0) == '+' {
				chomping = 1
			} else {
				chomping = -1
			}
			s.advance()
		}
	}
	for isBlank(s.peek(0)) {
		s.advance()
	}
	if s.peek(0) == '#' {
		for !s.eof(0) && !isBreak(s.peek(0)) {
			s.advance()
		}
	}
	if !s.eof(0) && !isBreak(s.peek(0)) {
		s.err = &scanErr{scanner: true, context: start, problem: s.mk, problemText: "did not find expected comment or line break"}
		return false
	}
	if !s.eof(0) {
		s.skipBreak()
	}
	indent := 0
	if increment > 0 {
		if s.indent >= 0 {
			indent = s.indent + increment
		} else {
			indent = increment
		}
	}
	var sb strings.Builder
	var leadingBreak, trailingBreaks strings.Builder
	// determine indentation
	maxIndent := 0
	for {
		for (indent == 0 || s.mk.col < indent) && s.peek(0) == ' ' {
			s.advance()
		}
		if s.mk.col > maxIndent {
			maxIndent = s.mk.col
		}
		if (indent == 0 || s.mk.col < indent) && !s.eof(0) && isBreak(s.peek(0)) {
			trailingBreaks.WriteString("\n")
			s.skipBreak()
		} else {
			break
		}
	}
	if indent == 0 {
		indent = maxIndent
		if indent < s.indent+1 {
			indent = s.indent + 1
		}
		if indent < 1 {
			indent = 1
		}
	}
	leadingBlank := false
	trailingBlank := false
	for s.mk.col == indent && !s.eof(0) {
		trailingBlank = isBlank(s.peek(0))
		if !literal && leadingBreak.Len() > 0 && !leadingBlank && !trailingBlank {
			if trailingBreaks.Len() == 0 {
				sb.WriteString(" ")
			}
			leadingBreak.Reset()
		} else {
			sb.WriteString(leadingBreak.String())
			leadingBreak.Reset()
		}
		sb.WriteString(trailingBreaks.String())
		trailingBreaks.Reset()
		leadingBlank = isBlank(s.peek(0))
		for !s.eof(0) && !isBreak(s.peek(0)) {
			sb.WriteRune(s.peek(0))
			s.advance()
		}
		if s.eof(0) {
			break
		}
		leadingBreak.WriteString("\n")
		s.skipBreak()
		for {
			for (indent == 0 || s.mk.col < indent) && s.peek(0) == ' ' {
				s.advance()
			}
			if (indent == 0 || s.mk.col < indent) && !s.eof(0) && isBreak(s.peek(0)) {
				trailingBreaks.WriteString("\n")
				s.skipBreak()
			} else {
				break
			}
		}
	}
	if chomping != -1 {
		sb.WriteString(leadingBreak.String())
	}
	if chomping == 1 {
		sb.WriteString(trailingBreaks.String())
	}
	st := styleLiteral
	if !literal {
		st = styleFolded
	}
	s.toks = append(s.toks, token{kind: tScalar, value: sb.String(), style: st, start: start, end: s.mk})
	return true
}
