package yamlite

import (
	"fmt"
	"math"
	"regexp"
	"strconv"
	"strings"
)

// Kind identifies the node variety.
type Kind int

const (
	ScalarNode Kind = iota
	SequenceNode
	MappingNode
)

// Node is a parsed YAML node.
type Node struct {
	Kind   Kind
	Value  string
	Quoted bool
	Line   int // 1-based
	Items  []*Node
	Keys   []*Node
	Values []*Node
}

type parser struct {
	s *scanner
}

func (p *parser) fail(contextMark mark, problem string, problemMark mark) *scanErr {
	return &scanErr{scanner: false, context: contextMark, problem: problemMark, problemText: problem}
}

func (p *parser) peek() (token, *scanErr) {
	t, ok := p.s.peekTok()
	if !ok {
		if p.s.err != nil {
			return token{}, p.s.err
		}
		return token{kind: tStreamEnd}, nil
	}
	return t, nil
}

func (p *parser) next() (token, *scanErr) {
	t, ok := p.s.next()
	if !ok {
		if p.s.err != nil {
			return token{}, p.s.err
		}
		return token{kind: tStreamEnd}, nil
	}
	return t, nil
}

// Parse parses the first document of a YAML stream. A nil node means the
// document is empty.
func Parse(src string) (*Node, error) {
	p := &parser{s: newScanner(src)}
	n, e := p.parseStream()
	if e != nil {
		return nil, formatErr(e)
	}
	return n, nil
}

func (p *parser) parseStream() (*Node, *scanErr) {
	t, e := p.next()
	if e != nil {
		return nil, e
	}
	if t.kind != tStreamStart {
		return nil, p.fail(mark{}, "did not find expected <stream-start>", t.start)
	}
	t, e = p.peek()
	if e != nil {
		return nil, e
	}
	if t.kind == tStreamEnd {
		return nil, nil
	}
	// implicit or explicit document start
	if t.kind == tDocStart {
		p.next()
		t, e = p.peek()
		if e != nil {
			return nil, e
		}
		if t.kind == tDocStart || t.kind == tDocEnd || t.kind == tStreamEnd {
			return nil, nil
		}
	}
	n, e := p.parseNode(true, false)
	if e != nil {
		return nil, e
	}
	t, e = p.peek()
	if e != nil {
		return nil, e
	}
	if t.kind == tDocEnd {
		p.next()
	}
	return n, nil
}

func emptyScalar(mk mark) *Node {
	return &Node{Kind: ScalarNode, Value: "", Line: mk.line + 1}
}

func (p *parser) parseNode(block bool, indentlessSeq bool) (*Node, *scanErr) {
	t, e := p.peek()
	if e != nil {
		return nil, e
	}
	switch t.kind {
	case tScalar:
		p.next()
		return &Node{Kind: ScalarNode, Value: t.value, Quoted: t.style != stylePlain, Line: t.start.line + 1}, nil
	case tFlowSeqStart:
		p.next()
		return p.parseFlowSeq(t.start)
	case tFlowMapStart:
		p.next()
		return p.parseFlowMap(t.start)
	case tBlockSeqStart:
		if block {
			p.next()
			return p.parseBlockSeq(t.start)
		}
	case tBlockMapStart:
		if block {
			p.next()
			return p.parseBlockMap(t.start)
		}
	case tBlockEntry:
		if indentlessSeq {
			return p.parseIndentlessSeq(t.start)
		}
	}
	ctx := "while parsing a flow node"
	if block {
		ctx = "while parsing a block node"
	}
	_ = ctx
	return nil, p.fail(t.start, "did not find expected node content", t.start)
}

func (p *parser) parseBlockMap(start mark) (*Node, *scanErr) {
	n := &Node{Kind: MappingNode, Line: start.line + 1}
	for {
		t, e := p.peek()
		if e != nil {
			return nil, e
		}
		switch t.kind {
		case tKey:
			p.next()
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			var key *Node
			if nt.kind == tKey || nt.kind == tValue || nt.kind == tBlockEnd {
				key = emptyScalar(t.end)
			} else {
				key, e = p.parseNode(true, true)
				if e != nil {
					return nil, e
				}
			}
			vt, e := p.peek()
			if e != nil {
				return nil, e
			}
			var val *Node
			if vt.kind == tValue {
				p.next()
				nt, e := p.peek()
				if e != nil {
					return nil, e
				}
				if nt.kind == tKey || nt.kind == tValue || nt.kind == tBlockEnd {
					val = emptyScalar(vt.end)
				} else {
					val, e = p.parseNode(true, true)
					if e != nil {
						return nil, e
					}
				}
			} else {
				val = emptyScalar(vt.start)
			}
			n.Keys = append(n.Keys, key)
			n.Values = append(n.Values, val)
		case tValue:
			// value without a key
			p.next()
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			key := emptyScalar(t.start)
			var val *Node
			if nt.kind == tKey || nt.kind == tValue || nt.kind == tBlockEnd {
				val = emptyScalar(t.end)
			} else {
				val, e = p.parseNode(true, true)
				if e != nil {
					return nil, e
				}
			}
			n.Keys = append(n.Keys, key)
			n.Values = append(n.Values, val)
		case tBlockEnd:
			p.next()
			return n, nil
		default:
			return nil, p.fail(start, "did not find expected key", t.start)
		}
	}
}

func (p *parser) parseBlockSeq(start mark) (*Node, *scanErr) {
	n := &Node{Kind: SequenceNode, Line: start.line + 1}
	for {
		t, e := p.peek()
		if e != nil {
			return nil, e
		}
		switch t.kind {
		case tBlockEntry:
			p.next()
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			if nt.kind == tBlockEntry || nt.kind == tBlockEnd {
				n.Items = append(n.Items, emptyScalar(t.end))
			} else {
				item, e := p.parseNode(true, false)
				if e != nil {
					return nil, e
				}
				n.Items = append(n.Items, item)
			}
		case tBlockEnd:
			p.next()
			return n, nil
		default:
			return nil, p.fail(start, "did not find expected '-' indicator", t.start)
		}
	}
}

func (p *parser) parseIndentlessSeq(start mark) (*Node, *scanErr) {
	n := &Node{Kind: SequenceNode, Line: start.line + 1}
	for {
		t, e := p.peek()
		if e != nil {
			return nil, e
		}
		if t.kind != tBlockEntry {
			return n, nil
		}
		p.next()
		nt, e := p.peek()
		if e != nil {
			return nil, e
		}
		if nt.kind == tBlockEntry || nt.kind == tKey || nt.kind == tValue || nt.kind == tBlockEnd {
			n.Items = append(n.Items, emptyScalar(t.end))
		} else {
			item, e := p.parseNode(true, false)
			if e != nil {
				return nil, e
			}
			n.Items = append(n.Items, item)
		}
	}
}

func (p *parser) parseFlowSeq(start mark) (*Node, *scanErr) {
	n := &Node{Kind: SequenceNode, Line: start.line + 1}
	first := true
	for {
		t, e := p.peek()
		if e != nil {
			return nil, e
		}
		if t.kind == tFlowSeqEnd {
			p.next()
			return n, nil
		}
		if !first {
			if t.kind == tFlowEntry {
				p.next()
				t, e = p.peek()
				if e != nil {
					return nil, e
				}
				if t.kind == tFlowSeqEnd {
					p.next()
					return n, nil
				}
			} else {
				return nil, p.fail(start, "did not find expected ',' or ']'", t.start)
			}
		}
		first = false
		if t.kind == tKey {
			// single-pair mapping inside a flow sequence
			p.next()
			m := &Node{Kind: MappingNode, Line: t.start.line + 1}
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			var key *Node
			if nt.kind == tValue || nt.kind == tFlowEntry || nt.kind == tFlowSeqEnd {
				key = emptyScalar(t.end)
			} else {
				key, e = p.parseNode(false, false)
				if e != nil {
					return nil, e
				}
			}
			vt, e := p.peek()
			if e != nil {
				return nil, e
			}
			var val *Node
			if vt.kind == tValue {
				p.next()
				nt, e := p.peek()
				if e != nil {
					return nil, e
				}
				if nt.kind == tFlowEntry || nt.kind == tFlowSeqEnd {
					val = emptyScalar(vt.end)
				} else {
					val, e = p.parseNode(false, false)
					if e != nil {
						return nil, e
					}
				}
			} else {
				val = emptyScalar(vt.start)
			}
			m.Keys = append(m.Keys, key)
			m.Values = append(m.Values, val)
			n.Items = append(n.Items, m)
			continue
		}
		item, e := p.parseNode(false, false)
		if e != nil {
			return nil, e
		}
		n.Items = append(n.Items, item)
	}
}

func (p *parser) parseFlowMap(start mark) (*Node, *scanErr) {
	n := &Node{Kind: MappingNode, Line: start.line + 1}
	first := true
	for {
		t, e := p.peek()
		if e != nil {
			return nil, e
		}
		if t.kind == tFlowMapEnd {
			p.next()
			return n, nil
		}
		if !first {
			if t.kind == tFlowEntry {
				p.next()
				t, e = p.peek()
				if e != nil {
					return nil, e
				}
				if t.kind == tFlowMapEnd {
					p.next()
					return n, nil
				}
			} else {
				return nil, p.fail(start, "did not find expected ',' or '}'", t.start)
			}
		}
		first = false
		var key *Node
		if t.kind == tKey {
			p.next()
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			if nt.kind == tValue || nt.kind == tFlowEntry || nt.kind == tFlowMapEnd {
				key = emptyScalar(t.end)
			} else {
				key, e = p.parseNode(false, false)
				if e != nil {
					return nil, e
				}
			}
		} else if t.kind == tValue {
			key = emptyScalar(t.start)
		} else {
			key, e = p.parseNode(false, false)
			if e != nil {
				return nil, e
			}
		}
		vt, e := p.peek()
		if e != nil {
			return nil, e
		}
		var val *Node
		if vt.kind == tValue {
			p.next()
			nt, e := p.peek()
			if e != nil {
				return nil, e
			}
			if nt.kind == tFlowEntry || nt.kind == tFlowMapEnd {
				val = emptyScalar(vt.end)
			} else {
				val, e = p.parseNode(false, false)
				if e != nil {
					return nil, e
				}
			}
		} else {
			val = emptyScalar(vt.start)
		}
		n.Keys = append(n.Keys, key)
		n.Values = append(n.Values, val)
	}
}

// ---- tag resolution -------------------------------------------------------

const (
	TagNull  = "!!null"
	TagBool  = "!!bool"
	TagInt   = "!!int"
	TagFloat = "!!float"
	TagStr   = "!!str"
	TagSeq   = "!!seq"
	TagMap   = "!!map"
	TagTime  = "!!timestamp"
)

var (
	reInt   = regexp.MustCompile(`^[-+]?(0|[1-9][0-9_]*)$`)
	reHex   = regexp.MustCompile(`^[-+]?0x[0-9a-fA-F_]+$`)
	reOct   = regexp.MustCompile(`^[-+]?0o[0-7_]+$`)
	reBin   = regexp.MustCompile(`^[-+]?0b[01_]+$`)
	reFloat = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)
	reTime  = regexp.MustCompile(`^[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}([Tt ]|$)`)
)

// Tag resolves the YAML tag of a node.
func (n *Node) Tag() string {
	switch n.Kind {
	case SequenceNode:
		return TagSeq
	case MappingNode:
		return TagMap
	}
	if n.Quoted {
		return TagStr
	}
	v := n.Value
	switch v {
	case "", "~", "null", "Null", "NULL":
		return TagNull
	case "true", "True", "TRUE", "false", "False", "FALSE":
		return TagBool
	case ".inf", ".Inf", ".INF", "+.inf", "+.Inf", "+.INF", "-.inf", "-.Inf", "-.INF", ".nan", ".NaN", ".NAN":
		return TagFloat
	}
	if v[0] == '-' || v[0] == '+' || v[0] == '.' || (v[0] >= '0' && v[0] <= '9') {
		if reInt.MatchString(v) || reHex.MatchString(v) || reOct.MatchString(v) || reBin.MatchString(v) {
			return TagInt
		}
		if reFloat.MatchString(v) {
			return TagFloat
		}
		if reTime.MatchString(v) {
			return TagTime
		}
	}
	return TagStr
}

// IsNull reports whether the scalar resolves to null.
func (n *Node) IsNull() bool {
	return n != nil && n.Kind == ScalarNode && n.Tag() == TagNull
}

// Decoder collects type errors in the style of the reference library.
type Decoder struct {
	errs []string
}

func (d *Decoder) terror(n *Node, typeName string) {
	tag := n.Tag()
	value := ""
	if tag != TagSeq && tag != TagMap {
		if len(n.Value) > 10 {
			value = " `" + n.Value[:7] + "...`"
		} else {
			value = " `" + n.Value + "`"
		}
	}
	d.errs = append(d.errs, fmt.Sprintf("line %d: cannot unmarshal %s%s into %s", n.Line, tag, value, typeName))
}

// Err returns the aggregated error, if any.
func (d *Decoder) Err() error {
	if len(d.errs) == 0 {
		return nil
	}
	return &Error{msg: "yaml: unmarshal errors:\n  " + strings.Join(d.errs, "\n  ")}
}

// String decodes a scalar node into a string.
func (d *Decoder) String(n *Node, out *string) {
	if n == nil {
		return
	}
	if n.Kind != ScalarNode {
		d.terror(n, "string")
		return
	}
	if n.IsNull() {
		*out = ""
		return
	}
	*out = n.Value
}

// Bool decodes a scalar node into a bool.
func (d *Decoder) Bool(n *Node, out *bool) {
	if n == nil {
		return
	}
	if n.Kind != ScalarNode {
		d.terror(n, "bool")
		return
	}
	tag := n.Tag()
	switch tag {
	case TagNull:
		*out = false
		return
	case TagBool:
		*out = strings.EqualFold(n.Value, "true")
		return
	case TagStr:
		switch n.Value {
		case "y", "Y", "yes", "Yes", "YES", "on", "On", "ON":
			*out = true
			return
		case "n", "N", "no", "No", "NO", "off", "Off", "OFF":
			*out = false
			return
		}
	}
	d.terror(n, "bool")
}

// StringSlice decodes a sequence of scalars into a string slice.
func (d *Decoder) StringSlice(n *Node, out *[]string) {
	if n == nil {
		return
	}
	if n.Kind == ScalarNode {
		if n.IsNull() {
			*out = nil
			return
		}
		d.terror(n, "[]string")
		return
	}
	if n.Kind != SequenceNode {
		d.terror(n, "[]string")
		return
	}
	res := make([]string, 0, len(n.Items))
	for _, it := range n.Items {
		var s string
		if it.Kind != ScalarNode {
			d.terror(it, "string")
			res = append(res, "")
			continue
		}
		d.String(it, &s)
		res = append(res, s)
	}
	*out = res
}

// KV is a mapping entry.
type KV struct {
	Key   string
	Value *Node
}

// Mapping decodes a mapping node into ordered key/value pairs, reporting
// duplicate keys. typeName is used in type errors.
func (d *Decoder) Mapping(n *Node, typeName string) []KV {
	if n == nil {
		return nil
	}
	if n.Kind == ScalarNode && n.IsNull() {
		return nil
	}
	if n.Kind != MappingNode {
		d.terror(n, typeName)
		return nil
	}
	seen := map[string]int{}
	var res []KV
	for i, k := range n.Keys {
		if k.Kind != ScalarNode {
			continue
		}
		key := k.Value
		if line, ok := seen[key]; ok {
			d.errs = append(d.errs, fmt.Sprintf("line %d: mapping key %#v already defined at line %d", k.Line, key, line))
			continue
		}
		seen[key] = k.Line
		res = append(res, KV{Key: key, Value: n.Values[i]})
	}
	return res
}

// Sequence returns the items of a sequence node, reporting a type error
// otherwise. typeName describes the slice type.
func (d *Decoder) Sequence(n *Node, typeName string) ([]*Node, bool) {
	if n == nil {
		return nil, false
	}
	if n.Kind == ScalarNode && n.IsNull() {
		return nil, false
	}
	if n.Kind != SequenceNode {
		d.terror(n, typeName)
		return nil, false
	}
	return n.Items, true
}

