// Package config loads and validates the application configuration.
package config

import (
	"fmt"
	"os"
	"path/filepath"

	"cheatclone/internal/homedir"
	"cheatclone/internal/yamlite"
)

// Cheatpath describes a directory containing cheatsheets.
type Cheatpath struct {
	Name     string
	Path     string
	ReadOnly bool
	Tags     []string
}

// Config is the application configuration.
type Config struct {
	Editor     string
	Colorize   bool
	Style      string
	Formatter  string
	Pager      string
	Cheatpaths []Cheatpath
}

// Load reads, parses and validates the configuration at path. Warnings are
// written to stderr.
func Load(path string) (Config, error) {
	var conf Config
	data, err := os.ReadFile(path)
	if err != nil {
		return conf, fmt.Errorf("could not read config file: %v", err)
	}
	if err := unmarshal(string(data), &conf); err != nil {
		return conf, fmt.Errorf("could not unmarshal yaml: %v", err)
	}

	// environment overrides for the editor
	if v := os.Getenv("VISUAL"); v != "" {
		conf.Editor = v
	} else if v := os.Getenv("EDITOR"); v != "" {
		conf.Editor = v
	}

	// expand and normalise cheatpaths, dropping those that do not exist
	var kept []Cheatpath
	for _, cp := range conf.Cheatpaths {
		expanded, err := homedir.Expand(cp.Path)
		if err != nil {
			return conf, fmt.Errorf("failed to expand ~: %v", err)
		}
		cp.Path = filepath.Clean(expanded)
		if _, err := os.Stat(cp.Path); err != nil {
			fmt.Fprintf(os.Stderr, "WARNING: cheatpath '%s' does not exist, skipping\n", cp.Path)
			continue
		}
		kept = append(kept, cp)
	}
	conf.Cheatpaths = kept

	// directory-scoped cheatpath
	if local, ok := localCheatpath(); ok {
		conf.Cheatpaths = append(conf.Cheatpaths, Cheatpath{Name: "cwd", Path: local})
	}

	if err := conf.validate(); err != nil {
		return conf, err
	}
	return conf, nil
}

func (c *Config) validate() error {
	if c.Editor == "" {
		return fmt.Errorf("no editor set")
	}
	names := map[string]bool{}
	paths := map[string]bool{}
	for _, cp := range c.Cheatpaths {
		if cp.Name == "" {
			return fmt.Errorf("config error: cheatpath name cannot be empty")
		}
		if names[cp.Name] {
			return fmt.Errorf("config error: cheatpath name is not unique: %s", cp.Name)
		}
		names[cp.Name] = true
		if paths[cp.Path] {
			return fmt.Errorf("config error: cheatpath path is not unique: %s", cp.Path)
		}
		paths[cp.Path] = true
	}
	if len(c.Cheatpaths) == 0 {
		return fmt.Errorf("config error: no cheatpaths specified")
	}
	switch c.Formatter {
	case "":
		c.Formatter = "terminal"
	case "terminal", "terminal256", "terminal16m":
	default:
		return fmt.Errorf("config error: formatter is invalid: %s", c.Formatter)
	}
	if c.Style == "" {
		c.Style = "bw"
	}
	return nil
}

// localCheatpath searches the working directory and its ancestors for a
// ".cheat" directory.
func localCheatpath() (string, bool) {
	cwd, err := os.Getwd()
	if err != nil {
		return "", false
	}
	dir := cwd
	for {
		candidate := filepath.Join(dir, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

func unmarshal(src string, conf *Config) error {
	root, err := yamlite.Parse(src)
	if err != nil {
		return err
	}
	d := &yamlite.Decoder{}
	for _, kv := range d.Mapping(root, "config.Config") {
		switch kv.Key {
		case "editor":
			d.String(kv.Value, &conf.Editor)
		case "colorize":
			d.Bool(kv.Value, &conf.Colorize)
		case "style":
			d.String(kv.Value, &conf.Style)
		case "formatter":
			d.String(kv.Value, &conf.Formatter)
		case "pager":
			d.String(kv.Value, &conf.Pager)
		case "cheatpaths":
			items, ok := d.Sequence(kv.Value, "[]cheatpath.Path")
			if !ok {
				continue
			}
			for _, item := range items {
				var cp Cheatpath
				for _, f := range d.Mapping(item, "cheatpath.Path") {
					switch f.Key {
					case "name":
						d.String(f.Value, &cp.Name)
					case "path":
						d.String(f.Value, &cp.Path)
					case "readonly":
						d.Bool(f.Value, &cp.ReadOnly)
					case "tags":
						d.StringSlice(f.Value, &cp.Tags)
					}
				}
				conf.Cheatpaths = append(conf.Cheatpaths, cp)
			}
		}
	}
	return d.Err()
}
