	dir := cwd
	for {
		candidate := filepath.Join(dir, ".cheat")
		if info, err := os.Stat(candidate); err == nil && info.IsDir() {
			return candidate, true
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", false
		}
		dir = parent
	}
}

func unmarshal(src string, conf *Config) error {
	root, err := yamlite.Parse(src)
	if err != nil {
		return err
	}
	d := &yamlite.Decoder{}
	for _, kv := range d.Mapping(root, "config.Config") {
		switch kv.Key {
		case "editor":
			d.String(kv.Value, &conf.Editor)
		case "colorize":
			d.Bool(kv.Value, &conf.Colorize)
		case "style":
			d.String(kv.Value, &conf.Style)
		case "formatter":
			d.String(kv.Value, &conf.Formatter)
		case "pager":
			d.String(kv.Value, &conf.Pager)
		case "cheatpaths":
			items, ok := d.Sequence(kv.Value, "[]cheatpath.Path")
			if !ok {
				continue
			}
			for _, item := range items {
				var cp Cheatpath
				for _, f := range d.Mapping(item, "cheatpath.Path") {
					switch f.Key {
					case "name":
						d.String(f.Value, &cp.Name)
					case "path":
						d.String(f.Value, &cp.Path)
					case "readonly":
						d.Bool(f.Value, &cp.ReadOnly)
					case "tags":
						d.StringSlice(f.Value, &cp.Tags)
					}
				}
				conf.Cheatpaths = append(conf.Cheatpaths, cp)
			}
		}
	}
	return d.Err()
}
