package highlight

import "strings"

// Trilean is a three-valued flag used for inheritable style attributes.
type Trilean int

// Trilean values.
const (
	Pass Trilean = iota
	Yes
	No
)

// StyleEntry describes how a token type is rendered.
type StyleEntry struct {
	Colour     Colour
	Background Colour
	Border     Colour
	Bold       Trilean
	Italic     Trilean
	Underline  Trilean
	NoInherit  Trilean
}

// IsZero reports whether the entry sets nothing.
func (s StyleEntry) IsZero() bool {
	return s.Colour == 0 && s.Background == 0 && s.Border == 0 && s.Bold == Pass && s.Italic == Pass && s.Underline == Pass && s.NoInherit == Pass
}

// Inherit fills unset attributes from ancestors, oldest first.
func (s StyleEntry) Inherit(ancestors ...StyleEntry) StyleEntry {
	out := s
	for i := len(ancestors) - 1; i >= 0; i-- {
		a := ancestors[i]
		if !out.Colour.IsSet() {
			out.Colour = a.Colour
		}
		if !out.Background.IsSet() {
			out.Background = a.Background
		}
		if !out.Border.IsSet() {
			out.Border = a.Border
		}
		if out.Bold == Pass {
			out.Bold = a.Bold
		}
		if out.Italic == Pass {
			out.Italic = a.Italic
		}
		if out.Underline == Pass {
			out.Underline = a.Underline
		}
		if out.NoInherit == Pass {
			out.NoInherit = a.NoInherit
		}
	}
	return out
}

func parseEntry(desc string) StyleEntry {
	var e StyleEntry
	for _, part := range strings.Fields(desc) {
		switch {
		case part == "bold":
			e.Bold = Yes
		case part == "nobold":
			e.Bold = No
		case part == "italic":
			e.Italic = Yes
		case part == "noitalic":
			e.Italic = No
		case part == "underline":
			e.Underline = Yes
		case part == "nounderline":
			e.Underline = No
		case part == "inherit":
			e.NoInherit = No
		case part == "noinherit":
			e.NoInherit = Yes
		case strings.HasPrefix(part, "bg:"):
			e.Background = ParseColour(part[3:])
		case strings.HasPrefix(part, "border:"):
			e.Border = ParseColour(part[7:])
		case strings.HasPrefix(part, "#"):
			e.Colour = ParseColour(part)
		}
	}
	return e
}

// Style maps token types to entries.
type Style struct {
	Name    string
	entries map[TokenType]StyleEntry
}

// NewStyle builds a style from entry descriptors.
func NewStyle(name string, descs map[TokenType]string) *Style {
	s := &Style{Name: name, entries: map[TokenType]StyleEntry{}}
	for t, d := range descs {
		s.entries[t] = parseEntry(d)
	}
	return s
}

// Types returns the explicitly styled token types.
func (s *Style) Types() []TokenType {
	out := make([]TokenType, 0, len(s.entries))
	for t := range s.entries {
		out = append(out, t)
	}
	return out
}

// Has reports whether the type has an explicit entry.
func (s *Style) Has(t TokenType) bool {
	_, ok := s.entries[t]
	return ok
}

func (s *Style) raw(t TokenType) StyleEntry { return s.entries[t] }

// Get returns the fully inherited entry for a token type.
func (s *Style) Get(t TokenType) StyleEntry {
	return s.raw(t).Inherit(
		s.raw(Background),
		s.raw(Text),
		s.raw(t.Category()),
		s.raw(t.SubCategory()),
	)
}

// ClearBackground returns a copy of the style whose base background colour
// has been removed, so that output does not paint the terminal.
func (s *Style) ClearBackground() *Style {
	out := &Style{Name: s.Name, entries: map[TokenType]StyleEntry{}}
	for k, v := range s.entries {
		out.entries[k] = v
	}
	bg := out.entries[Background]
	bg.Background = 0
	bg.NoInherit = Yes
	out.entries[Background] = bg
	return out
}

// ---- registry --------------------------------------------------------------

var styles = map[string]*Style{}

func registerStyle(s *Style) *Style {
	styles[s.Name] = s
	return s
}

// GetStyle looks up a style by name, falling back to "swapoff".
func GetStyle(name string) *Style {
	if s, ok := styles[name]; ok {
		return s
	}
	return styles["swapoff"]
}

