package highlight

import (
	"regexp"
	"strings"
	"unicode"
	"unicode/utf8"
)

// Unicode-aware character classes matching .NET style regex semantics.
const (
	clsWord  = `\p{L}\p{Mn}\p{Nd}\p{Pc}`
	clsSpace = `\t\n\v\f\r\x{85}\p{Z}`
)

// expand replaces \w \W \s \S \d shorthands with explicit Unicode classes.
func expand(pattern string) string {
	var sb strings.Builder
	inClass := false
	for i := 0; i < len(pattern); i++ {
		c := pattern[i]
		if c == '\\' && i+1 < len(pattern) {
			n := pattern[i+1]
			rep := ""
			switch n {
			case 'w':
				if inClass {
					rep = clsWord
				} else {
					rep = "[" + clsWord + "]"
				}
			case 'W':
				if inClass {
					rep = `\P{L}\P{Mn}\P{Nd}\P{Pc}` // approximation inside classes
				} else {
					rep = "[^" + clsWord + "]"
				}
			case 's':
				if inClass {
					rep = clsSpace
				} else {
					rep = "[" + clsSpace + "]"
				}
			case 'S':
				if inClass {
					rep = `\P{Z}` // approximation inside classes
				} else {
					rep = "[^" + clsSpace + "]"
				}
			case 'd':
				rep = `\p{Nd}`
			}
			if rep != "" {
				sb.WriteString(rep)
			} else {
				sb.WriteByte(c)
				sb.WriteByte(n)
			}
			i++
			continue
		}
		if c == '[' && !inClass {
			inClass = true
		} else if c == ']' && inClass {
			inClass = false
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r)
}

func isSpaceRune(r rune) bool {
	switch r {
	case '\t', '\n', '\v', '\f', '\r', 0x85:
		return true
	}
	return unicode.Is(unicode.Z, r)
}

// matcher attempts to match at the start of s (with the full text and
// position available for context) and returns the capture groups.
type matcher func(text string, pos int) []string

// emitter converts capture groups into tokens.
type emitter func(groups []string) []Token

type mutator struct {
	push string
	pop  bool
}

type rule struct {
	match  matcher
	emit   emitter
	mutate *mutator
}

type stateRules map[string][]rule

// Lexer is a state-machine regex lexer.
type Lexer struct {
	rules stateRules
}

func single(t TokenType) emitter {
	return func(groups []string) []Token {
		return []Token{{Type: t, Value: groups[0]}}
	}
}

func byGroups(types ...TokenType) emitter {
	return func(groups []string) []Token {
		out := make([]Token, 0, len(types))
		if len(types) != len(groups)-1 {
			return []Token{{Type: Error, Value: groups[0]}}
		}
		for i, t := range types {
			out = append(out, Token{Type: t, Value: groups[i+1]})
		}
		return out
	}
}

// re builds a matcher from a pattern anchored at the current position. A
// leading \b is checked manually against the preceding character.
func re(pattern string) matcher {
	wordStart := false
	if strings.HasPrefix(pattern, `\b`) {
		wordStart = true
		pattern = pattern[2:]
	}
	compiled := regexp.MustCompile(`^(?:` + expand(pattern) + `)`)
	return func(text string, pos int) []string {
		if wordStart {
			r, _ := utf8.DecodeRuneInString(text[pos:])
			if !isWordRune(r) {
				return nil
			}
			if pos > 0 {
				p, _ := utf8.DecodeLastRuneInString(text[:pos])
				if isWordRune(p) {
					return nil
				}
			}
		}
		return compiled.FindStringSubmatch(text[pos:])
	}
}

func push(state string) *mutator { return &mutator{push: state} }

var popState = &mutator{pop: true}

// Tokenise lexes text, coalescing adjacent tokens of the same type.
func (l *Lexer) Tokenise(text string) []Token {
	var out []Token
	stack := []string{"root"}
	pos := 0
	emit := func(t Token) {
		if t.Value == "" {
			return
		}
		if n := len(out); n > 0 && out[n-1].Type == t.Type && len(out[n-1].Value) < 8192 {
			out[n-1].Value += t.Value
			return
		}
		out = append(out, t)
	}
	for pos < len(text) {
		state := stack[len(stack)-1]
		var matched bool
		for _, r := range l.rules[state] {
			groups := r.match(text, pos)
			if groups == nil {
				continue
			}
			matched = true
			for _, t := range r.emit(groups) {
				emit(t)
			}
			pos += len(groups[0])
			if r.mutate != nil {
				if r.mutate.pop {
					if len(stack) > 1 {
						stack = stack[:len(stack)-1]
					}
				} else {
					stack = append(stack, r.mutate.push)
				}
			}
			break
		}
		if !matched {
			_, size := utf8.DecodeRuneInString(text[pos:])
			emit(Token{Type: Error, Value: text[pos : pos+size]})
			pos += size
		}
	}
	return out
}

// resolveIncludes expands include directives into flat rule lists.
type ruleSpec struct {
	include string
	r       rule
}

func inc(state string) ruleSpec { return ruleSpec{include: state} }

func rl(m matcher, e emitter, mut *mutator) ruleSpec {
	return ruleSpec{r: rule{match: m, emit: e, mutate: mut}}
}

func build(specs map[string][]ruleSpec) *Lexer {
	l := &Lexer{rules: stateRules{}}
	var resolve func(state string, seen map[string]bool) []rule
	resolve = func(state string, seen map[string]bool) []rule {
		var out []rule
		for _, s := range specs[state] {
			if s.include != "" {
				if seen[s.include] {
					continue
				}
				seen[s.include] = true
				out = append(out, resolve(s.include, seen)...)
				delete(seen, s.include)
				continue
			}
			out = append(out, s.r)
		}
		return out
	}
	for state := range specs {
		l.rules[state] = resolve(state, map[string]bool{state: true})
	}
	return l
}

// ---- registry --------------------------------------------------------------

var lexers = map[string]*Lexer{}

func registerLexer(l *Lexer, names ...string) {
	for _, n := range names {
		lexers[strings.ToLower(n)] = l
	}
}

// GetLexer returns the lexer for a syntax name, or the plaintext lexer.
func GetLexer(name string) *Lexer {
	if l, ok := lexers[strings.ToLower(name)]; ok {
		return l
	}
	return plaintext
}

var plaintext = &Lexer{rules: stateRules{
	"root": {{match: func(text string, pos int) []string { return []string{text[pos:]} }, emit: single(Text)}},
}}
