// Package cli implements command-line parsing with GNU-style long and short
// options, plus the application's commands.
package cli

import (
	"fmt"
	"strconv"
	"strings"
)

// Flag describes a single command-line option.
type Flag struct {
	Name      string
	Shorthand string
	Usage     string // may contain a `backticked` placeholder name
	IsBool    bool
	Hidden    bool

	Changed bool
	Value   string
	BoolVal bool
}

// FlagSet is an ordered collection of flags.
type FlagSet struct {
	flags      []*Flag
	byName     map[string]*Flag
	byShort    map[byte]*Flag
	Args       []string
	ArgsAtDash int
}

// NewFlagSet creates an empty flag set.
func NewFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, byShort: map[byte]*Flag{}, ArgsAtDash: -1}
}

// Bool registers a boolean flag.
func (fs *FlagSet) Bool(name, short, usage string) *Flag {
	return fs.add(&Flag{Name: name, Shorthand: short, Usage: usage, IsBool: true})
}

// String registers a string flag.
func (fs *FlagSet) String(name, short, usage string) *Flag {
	return fs.add(&Flag{Name: name, Shorthand: short, Usage: usage})
}

func (fs *FlagSet) add(f *Flag) *Flag {
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.byShort[f.Shorthand[0]] = f
	}
	return f
}

// Lookup finds a flag by long name.
func (fs *FlagSet) Lookup(name string) *Flag { return fs.byName[name] }

// LookupShort finds a flag by shorthand.
func (fs *FlagSet) LookupShort(c byte) *Flag { return fs.byShort[c] }

// Sorted returns the flags ordered lexicographically by name.
func (fs *FlagSet) Sorted() []*Flag {
	out := append([]*Flag{}, fs.flags...)
	for i := 1; i < len(out); i++ {
		for j := i; j > 0 && out[j-1].Name > out[j].Name; j-- {
			out[j-1], out[j] = out[j], out[j-1]
		}
	}
	return out
}

func (f *Flag) set(value string) error {
	if f.IsBool {
		v, err := strconv.ParseBool(value)
		if err != nil {
			name := "--" + f.Name
			if f.Shorthand != "" {
				name = "-" + f.Shorthand + ", --" + f.Name
			}
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, name, err)
		}
		f.BoolVal = v
	} else {
		f.Value = value
	}
	f.Changed = true
	return nil
}

// Parse processes the arguments, collecting positionals into Args.
func (fs *FlagSet) Parse(args []string) error {
	fs.Args = nil
	fs.ArgsAtDash = -1
	for len(args) > 0 {
		s := args[0]
		args = args[1:]
		if len(s) == 0 || s[0] != '-' || len(s) == 1 {
			fs.Args = append(fs.Args, s)
			continue
		}
		var err error
		if s[1] == '-' {
			if len(s) == 2 {
				fs.ArgsAtDash = len(fs.Args)
				fs.Args = append(fs.Args, args...)
				break
			}
			args, err = fs.parseLong(s, args)
		} else {
			args, err = fs.parseShort(s, args)
		}
		if err != nil {
			return err
		}
	}
	return nil
}

func (fs *FlagSet) parseLong(s string, args []string) ([]string, error) {
	name := s[2:]
	if len(name) == 0 || name[0] == '-' || name[0] == '=' {
		return args, fmt.Errorf("bad flag syntax: %s", s)
	}
	split := strings.SplitN(name, "=", 2)
	name = split[0]
	flag := fs.byName[name]
	if flag == nil {
		return args, fmt.Errorf("unknown flag: --%s", name)
	}
	var value string
	switch {
	case len(split) == 2:
		value = split[1]
	case flag.IsBool:
		value = "true"
	case len(args) > 0:
		value = args[0]
		args = args[1:]
	default:
		return args, fmt.Errorf("flag needs an argument: %s", s)
	}
	return args, flag.set(value)
}

func (fs *FlagSet) parseShort(s string, args []string) ([]string, error) {
	shorthands := s[1:]
	for len(shorthands) > 0 {
		var err error
		shorthands, args, err = fs.parseSingleShort(shorthands, args)
		if err != nil {
			return args, err
		}
	}
	return args, nil
}

func (fs *FlagSet) parseSingleShort(shorthands string, args []string) (string, []string, error) {
	outShorts := shorthands[1:]
	c := shorthands[0]
	flag := fs.byShort[c]
	if flag == nil {
		return outShorts, args, fmt.Errorf("unknown shorthand flag: %q in -%s", c, shorthands)
	}
	var value string
	switch {
	case len(shorthands) > 2 && shorthands[1] == '=':
		value = shorthands[2:]
		outShorts = ""
	case flag.IsBool:
		value = "true"
	case len(shorthands) > 1:
		value = shorthands[1:]
		outShorts = ""
	case len(args) > 0:
		value = args[0]
		args = args[1:]
	default:
		return outShorts, args, fmt.Errorf("flag needs an argument: %q in -%s", c, shorthands)
	}
	return outShorts, args, flag.set(value)
}
