// exitError carries an exit status alongside a message.
type exitError struct {
	code int
	msg  string
	out  io.Writer
}

func (e *exitError) Error() string { return e.msg }

func fail(code int, format string, args ...interface{}) *exitError {
	return &exitError{code: code, msg: fmt.Sprintf(format, args...), out: os.Stderr}
}

func notFound(title string) *exitError {
	return &exitError{code: 2, msg: fmt.Sprintf("No cheatsheet found for '%s'.", title), out: os.Stdout}
}

// Run executes the program with the given arguments and returns the exit
// status.
func Run(args []string) int {
	if len(args) > 0 && (args[0] == "__complete" || args[0] == "__completeNoDesc") {
		return runComplete(args[0] == "__completeNoDesc", args[1:])
	}
	opts := NewOptions()
	if err := opts.fs.Parse(args); err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}
	if opts.Help.BoolVal {
		fmt.Print(helpText)
		return 0
	}
	if len(opts.fs.Args) > 1 {
		fmt.Fprintf(os.Stderr, "accepts at most 1 arg(s), received %d\n", len(opts.fs.Args))
		return 1
	}
	err := run(opts)
	if err == nil {
		return 0
	}
	if ee, ok := err.(*exitError); ok {
		if ee.msg != "" {
			fmt.Fprintln(ee.out, ee.msg)
		}
		return ee.code
	}
	fmt.Fprintln(os.Stderr, err)
	return 1
}

func run(opts *Options) error {
	switch {
	case opts.Init.BoolVal:
		return cmdInit()
	case opts.Version.BoolVal:
		fmt.Println(Version)
		return nil
	case opts.Completion.Changed:
		return cmdCompletion(opts.Completion.Value)
	}

	confPath, conf, done, err := loadConfig()
	if err != nil {
		return err
	}
	if done {
		return nil
	}

