	paths := conf.Cheatpaths
	if opts.Path.Changed && opts.Path.Value != "" || opts.Path.Changed {
		var filtered []config.Cheatpath
		for _, cp := range paths {
			if cp.Name == opts.Path.Value {
				filtered = append(filtered, cp)
			}
		}
		if len(filtered) == 0 {
			return fail(1, "invalid option --path: cheatpath does not exist: %s", opts.Path.Value)
		}
		paths = filtered
	}

	switch {
	case opts.Directories.BoolVal:
		return cmdDirectories(paths, conf)
	case opts.Edit.Changed:
		return cmdEdit(opts, paths, conf)
	case opts.List.BoolVal || opts.Brief.BoolVal:
		return cmdList(opts, paths, conf)
	case opts.Tags.BoolVal:
		return cmdTags(paths, conf)
	case opts.Update.BoolVal:
		return cmdUpdate(paths)
	case opts.Search.Changed:
		return cmdSearch(opts, paths, conf, colorize)
	case opts.Rm.Changed:
		return cmdRemove(opts, paths)
	case len(opts.fs.Args) == 1:
		return cmdView(opts, paths, conf, colorize)
	}
	fmt.Print(helpText)
	return nil
}

// loadConfig locates and loads the configuration, running the installer when
// no config file exists. done reports that the installer handled the run.
func loadConfig() (string, config.Config, bool, error) {
	candidates, err := config.Candidates()
	if err != nil {
		return "", config.Config{}, false, fail(1, "failed to load config: %v", err)
	}
	confPath := config.Locate(candidates)
	if confPath == "" {
		confPath = candidates[0]
		created, err := installer.Run(confPath)
		if err != nil {
			return "", config.Config{}, false, fail(1, "%v", err)
		}
		if !created {
			return "", config.Config{}, true, nil
		}
		return confPath, config.Config{}, true, nil
	}
	conf, err := config.Load(confPath)
	if err != nil {
		return "", conf, false, fail(1, "failed to load config: %v", err)
	}
	return confPath, conf, false, nil
}

func cmdInit() error {
	candidates, err := config.Candidates()
	if err != nil {
		return fail(1, "failed to locate config: %v", err)
	}
	fmt.Println(config.Template(filepath.Dir(candidates[0])))
	return nil
}

func cmdCompletion(shell string) error {
	script, ok := completion.Script(shell)
	if !ok {
		return fail(1, "unsupported shell: %s (valid: bash, zsh, fish, powershell)", shell)
	}
	fmt.Print(script)
	return nil
}

func cmdDirectories(paths []config.Cheatpath, conf config.Config) error {
	var sb strings.Builder
	w := tabwriter.NewWriter(&sb, 0, 8, 1, ' ', 0)
	for _, cp := range paths {
		fmt.Fprintf(w, "%s:\t%s\n", cp.Name, cp.Path)
	}
	w.Flush()
	return writeOut(sb.String(), conf)
}

func writeOut(text string, conf config.Config) error {
	if err := display.Write(text, conf.Pager); err != nil {
		return fail(1, "%v", err)
	}
	return nil
}

func loadSheets(paths []config.Cheatpath) ([]map[string]sheets.Sheet, error) {
	all, err := sheets.Load(paths)
	if err != nil {
		return nil, fail(1, "failed to list cheatsheets: %v", err)
	}
	return all, nil
}

func cmdList(opts *Options, paths []config.Cheatpath, conf config.Config) error {
	all, err := loadSheets(paths)
	if err != nil {
		return err
	}
	all = sheets.FilterTag(all, opts.Tag.Value)
	flat := sheets.Flatten(all)
	sheets.SortByTitle(flat)

	if len(opts.fs.Args) == 1 {
		pattern := "(?i)" + opts.fs.Args[0]
		reg, err := regexp.Compile(pattern)
		if err != nil {
			return fail(1, "failed to compile regexp: %s, %v", pattern, err)
		}
		var filtered []sheets.Sheet
		for _, s := range flat {
			if reg.MatchString(s.Title) {
				filtered = append(filtered, s)
			}
		}
		flat = filtered
	}
	if len(flat) == 0 {
		return &exitError{code: 2}
	}

	var sb strings.Builder
	w := tabwriter.NewWriter(&sb, 0, 8, 1, ' ', 0)
	if opts.Brief.BoolVal {
		fmt.Fprintln(w, "title:\ttags:")
		for _, s := range flat {
			fmt.Fprintf(w, "%s\t%s\n", s.Title, strings.Join(s.Tags, ","))
		}
	} else {
		fmt.Fprintln(w, "title:\tfile:\ttags:")
		for _, s := range flat {
			fmt.Fprintf(w, "%s\t%s\t%s\n", s.Title, s.Path, strings.Join(s.Tags, ","))
		}
	}
	w.Flush()
	return writeOut(sb.String(), conf)
}

func cmdTags(paths []config.Cheatpath, conf config.Config) error {
