}

func cmdUpdate(paths []config.Cheatpath) error {
	var sb strings.Builder
	failed := false
	for _, cp := range paths {
		msg, isErr := update.Pull(cp.Path)
		if isErr {
			fmt.Fprintf(os.Stderr, "%s: %s\n", cp.Name, msg)
			failed = true
			continue
		}
		sb.WriteString(fmt.Sprintf("%s: %s\n", cp.Name, msg))
	}
	fmt.Print(sb.String())
	if failed {
		return &exitError{code: 1}
	}
	return nil
}

func colorizeSheet(s *sheets.Sheet, conf config.Config) {
	lexer := s.Syntax
	if lexer == "" {
		lexer = "bash"
	}
	s.Text = highlight.Highlight(s.Text, lexer, conf.Style, conf.Formatter)
}

func cmdSearch(opts *Options, paths []config.Cheatpath, conf config.Config, colorize bool) error {
	all, err := loadSheets(paths)
	if err != nil {
		return err
	}
	all = sheets.FilterTag(all, opts.Tag.Value)

	pattern := "(?i)" + opts.Search.Value
	if opts.Regex.BoolVal {
		pattern = opts.Search.Value
	}
	reg, err := regexp.Compile(pattern)
	if err != nil {
		return fail(1, "failed to compile regexp: %s, %v", pattern, err)
	}

	out := ""
	for _, s := range sheets.Flatten(all) {
		if len(opts.fs.Args) == 1 && s.Title != opts.fs.Args[0] {
			continue
		}
		s.Text = s.Search(reg)
		if s.Text == "" {
			continue
		}
		if colorize {
			colorizeSheet(&s, conf)
		}
		out += fmt.Sprintf("%s %s\n", s.Title, display.Faint("("+s.CheatPath+")", colorize))
		out += display.Indent(s.Text) + "\n"
	}
	out = strings.TrimSpace(out)
	return writeOut(out, conf)
}

func cmdView(opts *Options, paths []config.Cheatpath, conf config.Config, colorize bool) error {
	title := opts.fs.Args[0]
	all, err := loadSheets(paths)
	if err != nil {
		return err
	}
	all = sheets.FilterTag(all, opts.Tag.Value)

	if opts.All.BoolVal {
		out := ""
		for _, m := range all {
			s, ok := m[title]
			if !ok {
				continue
			}
			if colorize {
				colorizeSheet(&s, conf)
			}
			out += fmt.Sprintf("%s %s\n", s.Title, display.Faint("("+s.CheatPath+")", colorize))
			out += display.Indent(s.Text) + "\n\n"
		}
		out = strings.TrimSpace(out)
		if out == "" {
			return nil
		}
		return writeOut(out+"\n", conf)
	}

	consolidated := sheets.Consolidate(all)
	s, ok := consolidated[title]
	if !ok {
		return notFound(title)
	}
	if colorize {
		colorizeSheet(&s, conf)
	}
	return writeOut(s.Text, conf)
}

func cmdRemove(opts *Options, paths []config.Cheatpath) error {
	title := opts.Rm.Value
	all, err := loadSheets(paths)
	if err != nil {
		return err
	}
	all = sheets.FilterTag(all, opts.Tag.Value)
	s, ok := sheets.Consolidate(all)[title]
	if !ok {
		return notFound(title)
	}
	if s.ReadOnly {
		return fail(1, "cheatsheet '%s' is read-only.", title)
	}
	if err := os.Remove(s.Path); err != nil {
		return fail(1, "failed to delete sheet: %s, %v", title, err)
	}
	return nil
}

func cmdEdit(opts *Options, paths []config.Cheatpath, conf config.Config) error {
	title := opts.Edit.Value
	all, err := loadSheets(paths)
	if err != nil {
		return err
	}
	all = sheets.FilterTag(all, opts.Tag.Value)
	s, ok := sheets.Consolidate(all)[title]

	var editPath string
	if ok && !s.ReadOnly {
		editPath = s.Path
	} else {
		var writeable *config.Cheatpath
		for i := len(paths) - 1; i >= 0; i-- {
			if !paths[i].ReadOnly {
				writeable = &paths[i]
				break
			}
		}
		if writeable == nil {
			return fail(1, "failed to get writeable path: no writeable cheatpaths found")
		}
		editPath = filepath.Join(writeable.Path, title)
		dir := filepath.Dir(editPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fail(1, "failed to create directory: %s, %v", dir, err)
		}
		if ok {
			if err := copyFile(s.Path, editPath); err != nil {
				return fail(1, "failed to copy cheatsheet: %v", err)
			}
		}
	}

	parts := strings.Fields(conf.Editor)
	cmd := exec.Command(parts[0], append(parts[1:], editPath)...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fail(1, "failed to edit cheatsheet: %v", err)
	}
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return fmt.Errorf("failed to open infile: %s, %v", src, err)
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return fmt.Errorf("failed to create outfile: %s, %v", dst, err)
	}
	defer out.Close()
	if _, err := io.Copy(out, in); err != nil {
		return fmt.Errorf("failed to copy file: %v", err)
	}
	return nil
}

