package cli

import (
	"fmt"
	"os"
	"strings"

	"cheatclone/internal/config"
	"cheatclone/internal/sheets"
)

// Shell completion directives.
const (
	directiveError       = 1
	directiveNoSpace     = 2
	directiveNoFileComp  = 4
	directiveDefault     = 0
)

func directiveName(d int) string {
	if d == 0 {
		return "ShellCompDirectiveDefault"
	}
	var parts []string
	if d&directiveError != 0 {
		parts = append(parts, "ShellCompDirectiveError")
	}
	if d&directiveNoSpace != 0 {
		parts = append(parts, "ShellCompDirectiveNoSpace")
	}
	if d&directiveNoFileComp != 0 {
		parts = append(parts, "ShellCompDirectiveNoFileComp")
	}
	return strings.Join(parts, ", ")
}

// runComplete implements the hidden "__complete" command used by the shell
// completion scripts.
func runComplete(noDesc bool, args []string) int {
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "Error: requires at least 1 arg(s), only received 0")
		return 1
	}
	comps, directive := completions(args)
	for _, c := range comps {
		if noDesc {
			if idx := strings.Index(c, "\t"); idx >= 0 {
				c = c[:idx]
			}
		}
		fmt.Println(c)
	}
	fmt.Printf(":%d\n", directive)
	fmt.Fprintf(os.Stderr, "Completion ended with directive: %s\n", directiveName(directive))
	return 0
}

func isFlagArg(arg string) bool {
	return (len(arg) >= 3 && arg[0:2] == "--") || (len(arg) >= 2 && arg[0] == '-' && arg[1] != '-')
}

func completions(args []string) ([]string, int) {
	toComplete := args[len(args)-1]
	trimmed := args[:len(args)-1]
	opts := NewOptions()
	fs := opts.fs

	// Determine whether a flag value is being completed.
	var flag *Flag
	flagWithEqual := false
	flagErr := false
	flagName := ""
	finalArgs := trimmed
	if len(toComplete) > 0 && toComplete[0] == '-' {
		if idx := strings.Index(toComplete, "="); idx >= 0 {
			if strings.HasPrefix(toComplete[:idx], "--") {
				flagName = toComplete[2:idx]
			} else {
				flagName = toComplete[1:idx]
			}
			toComplete = toComplete[idx+1:]
			flagWithEqual = true
		}
	}
	if flagName == "" && len(trimmed) > 0 {
		prev := trimmed[len(trimmed)-1]
		if isFlagArg(prev) && !strings.Contains(prev, "=") {
			if strings.HasPrefix(prev, "--") {
				flagName = prev[2:]
			} else {
				flagName = prev[1:]
			}
			finalArgs = trimmed[:len(trimmed)-1]
		}
	}
	if flagName != "" {
		flag = fs.Lookup(flagName)
		if flag == nil && len(flagName) == 1 {
			flag = fs.LookupShort(flagName[0])
		}
		if flag == nil {
			flagErr = true
			finalArgs = trimmed
		} else if !flagWithEqual && flag.IsBool {
			flag = nil
			finalArgs = trimmed
		}
	}

	// Detect "--" on the command line.
	flagCompletion := true
	probe := NewOptions().fs
	_ = probe.Parse(append(append([]string{}, finalArgs...), "--"))
	newArgCount := len(probe.Args)

	if err := fs.Parse(finalArgs); err != nil {
		fmt.Fprintf(os.Stderr, "[Debug] [Error] Error while parsing flags from args %v: %s\n", finalArgs, err.Error())
		return nil, directiveDefault
	}
	if newArgCount > len(fs.Args) {
		flagCompletion = false
	}
	if flagErr && flagCompletion {
		fmt.Fprintf(os.Stderr, "[Debug] [Error] Subcommand '%s' does not support flag '%s'\n", "cheat", flagName)
		return nil, directiveDefault
	}
	if opts.Help.BoolVal {
		return nil, directiveNoFileComp
	}
	positional := fs.Args

	if flag == nil && len(toComplete) > 0 && toComplete[0] == '-' && !strings.Contains(toComplete, "=") && flagCompletion {
		var out []string
		for _, f := range fs.Sorted() {
			if f.Changed {
				continue
			}
			long := "--" + f.Name
			if strings.HasPrefix(long, toComplete) {
				out = append(out, long+"\t"+f.Usage)
			}
			if f.Shorthand != "" {
				short := "-" + f.Shorthand
				if strings.HasPrefix(short, toComplete) {
					out = append(out, short+"\t"+f.Usage)
				}
			}
		}
		directive := directiveNoFileComp
		if len(out) == 1 && strings.HasSuffix(out[0], "=") {
			directive = directiveNoSpace
		}
		return out, directive
	}

	if flag != nil && flagCompletion {
		switch flag.Name {
		case "path":
			return completePaths(), directiveNoFileComp
		case "tag":
			return completeTags(), directiveNoFileComp
		case "edit", "rm":
			return completeTitles(), directiveNoFileComp
		}
		return nil, directiveDefault
	}
	if flag != nil {
		return nil, directiveDefault
	}

	// positional completion
	if len(positional) != 0 {
		return nil, directiveNoFileComp
	}
	return completeTitles(), directiveNoFileComp
}

func quietConfig() (config.Config, bool) {
	candidates, err := config.Candidates()
	if err != nil {
		return config.Config{}, false
	}
	path := config.Locate(candidates)
	if path == "" {
		return config.Config{}, false
	}
	devnull, err := os.OpenFile(os.DevNull, os.O_WRONLY, 0)
	if err == nil {
		saved := os.Stderr
		os.Stderr = devnull
		defer func() {
			os.Stderr = saved
			devnull.Close()
		}()
	}
	conf, err := config.Load(path)
	if err != nil {
		return config.Config{}, false
	}
	return conf, true
}

func completePaths() []string {
	conf, ok := quietConfig()
	if !ok {
		return nil
	}
	var out []string
	for _, cp := range conf.Cheatpaths {
		out = append(out, cp.Name)
	}
	return out
}

func completeTags() []string {
	conf, ok := quietConfig()
	if !ok {
		return nil
	}
	all, err := sheets.Load(conf.Cheatpaths)
	if err != nil {
		return nil
	}
	return sheets.Tags(all)
}

func completeTitles() []string {
	conf, ok := quietConfig()
	if !ok {
		return nil
	}
	all, err := sheets.Load(conf.Cheatpaths)
	if err != nil {
		return nil
	}
	return sheets.Titles(all)
}
