	switch {
	case strings.HasPrefix(url, "http://") || strings.HasPrefix(url, "https://"):
		// Probe HTTP remotes first so that connectivity failures are
		// reported in a consistent manner.
		if err := Probe(url); err != nil {
			return fmt.Sprintf("error (%v)", err), true
		}
	case url != "" && !strings.Contains(url, "://") && !strings.Contains(url, ":"):
		local := strings.TrimPrefix(url, "file://")
		if !filepath.IsAbs(local) {
			local = filepath.Join(path, local)
		}
		if _, err := os.Stat(local); err != nil {
			return "error (repository not found)", true
		}
	}

	if _, err := git(path, "fetch", "origin"); err != nil {
		return fmt.Sprintf("error (%s)", err), true
	}

	// The remote's default branch is the merge target.
	lsOut, err := git(path, "ls-remote", "origin", "HEAD")
	if err != nil {
		return fmt.Sprintf("error (%s)", err), true
	}
	fields := strings.Fields(lsOut)
	if len(fields) == 0 {
		return "error (reference not found)", true
	}
	target := fields[0]

	head, err := git(path, "rev-parse", "--verify", "-q", "HEAD")
	if err != nil {
		// no local commits yet: adopt the remote state
		if _, err := git(path, "reset", "--hard", target); err != nil {
			return fmt.Sprintf("error (%s)", err), true
		}
		return "ok", false
	}
	head = strings.TrimSpace(head)
	if head == target {
		return "ok", false
	}
	// local history already contains the remote: nothing to do
	if _, err := git(path, "merge-base", "--is-ancestor", target, "HEAD"); err == nil {
		return "ok", false
	}
	if _, err := git(path, "merge-base", "--is-ancestor", "HEAD", target); err != nil {
		return "error (non-fast-forward update)", true
	}
	if _, err := git(path, "merge", "--ff-only", target); err != nil {
		return fmt.Sprintf("error (%s)", err), true
	}
	return "ok", false
