package main

import (
	"fmt"
	"math/rand"
	"time"

	"cheatclone/internal/highlight"
	"cheatclone/internal/yamlite"
)

func main() {
	alphabet := []rune("abc: -[]{},#\"'|>?!&*%@`\n\r\t 01\\é")
	r := rand.New(rand.NewSource(1))
	for i := 0; i < 200000; i++ {
		n := r.Intn(40)
		buf := make([]rune, n)
		for j := range buf {
			buf[j] = alphabet[r.Intn(len(alphabet))]
		}
		s := string(buf)
		done := make(chan bool, 1)
		go func() {
			defer func() {
				if e := recover(); e != nil {
					fmt.Printf("PANIC on %q: %v\n", s, e)
				}
				done <- true
			}()
			yamlite.Parse(s)
			highlight.Highlight(s, "bash", "monokai", "terminal256")
		}()
		select {
		case <-done:
		case <-time.After(2 * time.Second):
			fmt.Printf("HANG on %q\n", s)
			return
		}
	}
	fmt.Println("fuzz done")
}
EOF
